#include "stdlib/blas/ext/base/ndarray/dfill.h"
#include "stdlib/blas/ext/base/dfill.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/base/clip_index.h"
#include "stdlib/blas/base/shared.h"
#include <stdint.h>

/**
* Fills a one-dimensional double-precision floating-point ndarray with a specified scalar constant.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional float64 ndarray containing the scalar constant.
*     -   a zero-dimensional float64 ndarray containing the starting index (inclusive).
*     -   a zero-dimensional float64 ndarray containing the ending index (exclusive).
*
* @param arrays    list containing ndarrays
*/
void stdlib_blas_ext_dfill( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];

	double alpha;
	double s;
	double e;
	stdlib_ndarray_get_float64( arrays[ 1 ], NULL, &alpha );
	stdlib_ndarray_get_float64( arrays[ 2 ], NULL, &s );
	stdlib_ndarray_get_float64( arrays[ 3 ], NULL, &e );

	const int64_t N = stdlib_ndarray_dimension( x, 0 );
	// Bound indices before converting to integers:
	const int64_t start = ( s < -N ) ? 0 : ( s > N ) ? N : stdlib_ndarray_clip_index( (int64_t)s, N );
	const int64_t end = ( e < -N ) ? 0 : ( e > N ) ? N : stdlib_ndarray_clip_index( (int64_t)e, N );
	if ( start >= end ) {
		return;
	}
	const CBLAS_INT strideX = stdlib_ndarray_stride_elements( x, 0 );
	const CBLAS_INT offsetX = stdlib_ndarray_offset_elements( x ) + ( strideX*start );

	double *dataX = (double *)stdlib_ndarray_data( x );
	API_SUFFIX(stdlib_strided_dfill_ndarray)( end-start, alpha, dataX, strideX, offsetX );
}
